-- Generated by C++ build-import from the official CSV files.
BEGIN;
SELECT pg_advisory_xact_lock(3072026);
SET LOCAL search_path TO public;
SET LOCAL standard_conforming_strings=on;
DROP FUNCTION IF EXISTS get_station_n_neighbor(text,text,integer);
DROP TABLE IF EXISTS exit_landmark,station_exit,landmark,line_stop,station,metro_line,district;
-- PostgreSQL DDL only. Run in an empty project database/schema.
CREATE TABLE district (
    district_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name_en text NOT NULL UNIQUE
);
CREATE TABLE metro_line (
    line_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name_zh text NOT NULL UNIQUE,
    name_en text NOT NULL UNIQUE
);
CREATE TABLE station (
    station_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    district_id integer NOT NULL REFERENCES district(district_id),
    name_zh text NOT NULL,
    name_en text NOT NULL,
    latitude numeric(9,6),
    longitude numeric(9,6),
    CONSTRAINT station_name_district_key UNIQUE (name_zh, district_id),
    CONSTRAINT station_latitude_check CHECK (latitude BETWEEN -90 AND 90),
    CONSTRAINT station_longitude_check CHECK (longitude BETWEEN -180 AND 180),
    CONSTRAINT station_coordinates_check CHECK ((latitude IS NULL) = (longitude IS NULL))
);
CREATE TABLE line_stop (
    line_id integer NOT NULL REFERENCES metro_line(line_id),
    station_id integer NOT NULL REFERENCES station(station_id),
    position integer NOT NULL CHECK (position > 0),
    status text NOT NULL CHECK (status IN ('Operation', 'Construction')),
    opening_year smallint NOT NULL CHECK (opening_year > 0),
    first_train time,
    last_train time,
    PRIMARY KEY (line_id, station_id),
    CONSTRAINT line_stop_position_key UNIQUE (line_id, position)
        DEFERRABLE INITIALLY IMMEDIATE
);
CREATE TABLE station_exit (
    exit_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    station_id integer NOT NULL REFERENCES station(station_id),
    exit_code text NOT NULL,
    CONSTRAINT station_exit_code_key UNIQUE (station_id, exit_code)
);
CREATE TABLE landmark (
    landmark_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name text NOT NULL UNIQUE
);
CREATE TABLE exit_landmark (
    exit_id integer NOT NULL REFERENCES station_exit(exit_id),
    landmark_id integer NOT NULL REFERENCES landmark(landmark_id),
    PRIMARY KEY (exit_id, landmark_id)
);

SELECT setval(pg_get_serial_sequence('district','district_id'),(SELECT max(district_id) FROM district),true);
SELECT setval(pg_get_serial_sequence('metro_line','line_id'),(SELECT max(line_id) FROM metro_line),true);
SELECT setval(pg_get_serial_sequence('station','station_id'),(SELECT max(station_id) FROM station),true);
SELECT setval(pg_get_serial_sequence('station_exit','exit_id'),(SELECT max(exit_id) FROM station_exit),true);
SELECT setval(pg_get_serial_sequence('landmark','landmark_id'),(SELECT max(landmark_id) FROM landmark),true);
CREATE INDEX line_stop_station_idx ON line_stop(station_id);
CREATE INDEX exit_landmark_landmark_idx ON exit_landmark(landmark_id);
CREATE INDEX station_name_en_idx ON station(name_en);
CREATE INDEX landmark_prefix_idx ON landmark(name text_pattern_ops);
-- Returns lower-order neighbour first, then higher-order neighbour, like the PDF.
CREATE OR REPLACE FUNCTION get_station_n_neighbor(station_name text, line_name text, n integer)
RETURNS SETOF text
LANGUAGE plpgsql STABLE AS $$
DECLARE
    station_names text[];
    current_index integer;
    found_count integer;
BEGIN
    IF station_name IS NULL OR line_name IS NULL OR n IS NULL OR n < 0 THEN
        RAISE EXCEPTION 'Station, line and nonnegative n are required' USING ERRCODE = '22023';
    END IF;
    SELECT array_agg(s.name_en ORDER BY ls.position)
    INTO station_names
    FROM line_stop ls JOIN metro_line l USING (line_id) JOIN station s USING (station_id)
    WHERE l.name_en = line_name;
    SELECT count(*), min(i) INTO found_count, current_index
    FROM unnest(station_names) WITH ORDINALITY AS t(name, i) WHERE name = station_name;
    IF found_count <> 1 THEN
        RAISE EXCEPTION 'Expected one station % on line %, found %', station_name, line_name, found_count
            USING ERRCODE = '22023';
    END IF;
    RETURN NEXT CASE WHEN current_index::bigint - n >= 1 THEN station_names[current_index - n] END;
    RETURN NEXT CASE WHEN current_index::bigint + n <= cardinality(station_names) THEN station_names[current_index + n] END;
END;
$$;

COMMIT;
